from collections import deque
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # border-connected zeros
    seen=[[g[i][j]!=0 for j in range(w)] for i in range(h)]
    dq=deque()
    for i in range(h):
        for j in range(w):
            if (i in(0,h-1) or j in(0,w-1)) and g[i][j]==0:
                seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<h and 0<=b<w and not seen[a][b]:
                seen[a][b]=True; dq.append((a,b))
    # enclosed regions via BFS from inner 2s
    lab=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j] and lab[i][j]==0:
                # find nearest 2s (multi-source BFS from all 2s in component's bounding... use all 2s)
                dist={(i,j):0}; q=deque([(i,j)]); comp=[(i,j)]
                while q:
                    a,b=q.popleft()
                    for x,y in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<h and 0<=y<w and g[x][y]==0 and not seen[x][y] and (x,y) not in dist:
                            dist[(x,y)]=dist[(a,b)]+1; q.append((x,y)); comp.append((x,y))
                # multi-source from adjacent 2s of the component
                dist2={}
                q=deque()
                for a,b in comp:
                    for x,y in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<h and 0<=y<w and g[x][y]==2 and (a,b) not in dist2:
                            dist2[(a,b)]=1; q.append((a,b))
                while q:
                    a,b=q.popleft()
                    for x,y in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if (x,y) in dist and (x,y) not in dist2:
                            dist2[(x,y)]=dist2[(a,b)]+1; q.append((x,y))
                md=max(dist2.values())
                col=2**(4-md) if 0<=4-md<=3 else (8>>(md-1) if md>=1 else 8)
                for a,b in comp: out[a][b]=col
    return out
